INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46311, 'Ezekiel 18:16', 'Ezekiel', 18, 16, 'نه د چا سره ظلم کوي، نه د چا نه غلا کوي، په امانت کې خیانت نه کوي، وږیو خلکو ته خواړه ورکوي او لوڅو خلکو ته کالي ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_16.mp3', '', 1761754199, 1761754199),
(46312, 'Ezekiel 18:17', 'Ezekiel', 18, 17, 'هغه د غریبانو سره مرسته کوي او خپلې پیسې په سود نه ورکوي. هغه زما په حکمونو باندې عمل کوي او زما د قوانینو څخه پیروي کوي. هغه به د خپل پلار د ګناهونو په سبب مړ نه شي او خامخا به ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_17.mp3', '', 1761754199, 1761754199),
(46313, 'Ezekiel 18:18', 'Ezekiel', 18, 18, 'خو پلار به یې د خپلو ګناهونو په خاطر مړ شي، ځکه هغه به غلا کوله، د خلکو شتمني به یې په زوره غصبوله او د خپلو خلکو سره به یې بدي کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_18.mp3', '', 1761754199, 1761754199),
(46314, 'Ezekiel 18:19', 'Ezekiel', 18, 19, 'خو تاسو پوښتنه کوئ: ‹ولې زوی ته د خپل پلار د ګناهونو په سبب سزا نه ورکول کیږي؟› ځواب یې دا دی چې زوی هغه کار کاوه چې سم او ښه ؤ. هغه زما په قوانینو باندې عمل کاوه او په غور سره یې د هغو څخه پیروي کوله، نو هغه به خامخا ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_19.mp3', '', 1761754199, 1761754199),
(46315, 'Ezekiel 18:20', 'Ezekiel', 18, 20, 'څوک چې ګناه وکړي، نو هغه به مړ شي. زوی باید د خپل پلار د ګناهونو په خاطر ونه کړیږي او نه پلار د زوی د ګناهونو په خاطر. نېک انسان ته به د خپل نېک عمل اجر ورکول کیږي او بدعمله انسان به د خپلو بدو عملونو سزا مومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_20.mp3', '', 1761754199, 1761754199),
(46316, 'Ezekiel 18:21', 'Ezekiel', 18, 21, 'که چېرې یو بدعمله انسان د ګناه نه لاس واخلي او زما په ټولو قوانینو باندې عمل وکړي او عادلانه او ښه کارونه وکړي، نو هغه به مړ نه شي او خامخا به ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_21.mp3', '', 1761754199, 1761754199),
(46317, 'Ezekiel 18:22', 'Ezekiel', 18, 22, 'د هغه ټول ګناهونه به وبخښل شي او هغه به ژوندی پاتې شي، ځکه چې هغه ښه کارونه کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_22.mp3', '', 1761754199, 1761754199),
(46318, 'Ezekiel 18:23', 'Ezekiel', 18, 23, 'څښتن تعالی پوښتنه کوي: ‹ایا تاسو فکر کوئ چې زه د یو ګناهکار انسان په مرګ باندې خوشحالېږم؟› نه، بلکې زه غواړم چې هغه د خپلو بدو لارو نه راوګرځي او ژوندی پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_23.mp3', '', 1761754199, 1761754199),
(46319, 'Ezekiel 18:24', 'Ezekiel', 18, 24, 'خو که چېرې یو نېک انسان د خپلو ښو کارونو نه لاس واخلي او ټول بد عملونه او هغه د کرکې وړ کارونه پیل کړي چې بدکاره خلک یې کوي، ایا هغه به ژوندی پاتې شي؟ نه، د هغه ټول ښه کارونه به هېر شي. هغه به د خپلې بې‌وفایۍ او د خپلو ګناهونو له امله مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_24.mp3', '', 1761754199, 1761754199),
(46320, 'Ezekiel 18:25', 'Ezekiel', 18, 25, 'خو تاسو وایئ: ‹د څښتن کارونه عادلانه نه دي.› ای اسراییلیانو، ماته غوږ ونیسئ. ایا تاسو فکر کوئ چې زما لاره عادلانه نه ده؟ دا ستاسو لاره ده چې عادلانه نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_25.mp3', '', 1761754199, 1761754199),
(46321, 'Ezekiel 18:26', 'Ezekiel', 18, 26, 'کله چې یو نېک انسان د نېکو کارونو نه لاس واخلي او بد کارونه پیل کړي او بیا مړ شي، نو دا مړینه به د هغه د بد عمل په خاطر وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_26.mp3', '', 1761754199, 1761754199),
(46322, 'Ezekiel 18:27', 'Ezekiel', 18, 27, 'کله چې یو ګناهکار انسان د ګناه نه لاس واخلي او عادلانه او نېک کارونه کوي، نو هغه به خپل ژوند وژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_27.mp3', '', 1761754199, 1761754199),
(46323, 'Ezekiel 18:28', 'Ezekiel', 18, 28, 'هغه پوهیږي چې څه کوي او د ټولو ګناهونو نه لاس اخلي، نو هغه به خامخا ژوندی پاتې شي او مړ به نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_28.mp3', '', 1761754199, 1761754199),
(46324, 'Ezekiel 18:29', 'Ezekiel', 18, 29, 'خو تاسو اسراییلیان وایئ: ‹د څښتن کارونه عادلانه نه دي.› ایا تاسو فکر کوئ چې زما لاره عادلانه نه ده؟ دا ستاسو لاره ده چې عادلانه نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_29.mp3', '', 1761754199, 1761754199),
(46325, 'Ezekiel 18:30', 'Ezekiel', 18, 30, 'نو زه څښتن تعالی تاسو اسراییلیانو ته داسې وایم چې زه به ستاسو د هر یو په هکله ستاسو د عملونو له مخې قضاوت وکړم. توبه وباسئ او د خپلو ټولو بدو عملونو نه لاس واخلئ. که نه، نو مړه به شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_30.mp3', '', 1761754199, 1761754199),
(46326, 'Ezekiel 18:31', 'Ezekiel', 18, 31, 'تاسو چې کوم بد کارونه کوئ، د هغو ټولو نه لاس واخلئ او په خپلو ځانونو کې نوی زړه او تازه روح راپیدا کړئ. ای اسراییلیانو، تاسو ولې غواړئ چې مړه شئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_31.mp3', '', 1761754199, 1761754199),
(46327, 'Ezekiel 18:32', 'Ezekiel', 18, 32, 'څښتن تعالی وایي: ‹زه د هېچا په مرګ نه خوشحالېږم. د خپلو ګناهونو نه لاس واخلئ او ژوندي پاتې شئ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel18_verse_32.mp3', '', 1761754199, 1761754199),
(46328, 'Genesis 43:1', 'Genesis', 43, 1, 'په کنعان کې قحطي نوره هم سخته شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_1.mp3', '', 1761754199, 1761754199),
(46329, 'Genesis 43:2', 'Genesis', 43, 2, 'نو کله چې هغوی هغه ټوله غله چې د مصر څخه یې راوړې وه وخوړله، نو یعقوب خپلو زامنو ته وویل: «بېرته لاړ شئ او لږه نوره غله زمونږ دپاره واخلئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_2.mp3', '', 1761754199, 1761754199),
(46330, 'Genesis 43:3', 'Genesis', 43, 3, 'خو یهودا هغه ته وویل: «هغه سړي مونږ ته په ټینګه خبرداری راکړی دی چې ترڅو پورې چې ستاسو ورور ستاسو سره نه وي، زما مخ به بیا ونه وینئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_3.mp3', '', 1761754199, 1761754199),
(46331, 'Genesis 43:4', 'Genesis', 43, 4, 'که زمونږ ورور دې زمونږ سره ولېږه، نو مونږ به لاړ شو او ستا دپاره به خواړه واخلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_4.mp3', '', 1761754199, 1761754199),
(46332, 'Genesis 43:5', 'Genesis', 43, 5, 'خو که هغه دې ونه لېږه نو مونږ نه ځو، ځکه چې هغه سړي مونږ ته وویل چې ترڅو پورې ستاسو ورور ستاسو سره نه وي، نو نور به زما مخ ونه وینئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_5.mp3', '', 1761754199, 1761754199),
(46333, 'Genesis 43:6', 'Genesis', 43, 6, 'یعقوب وویل: «زه مو ولې د داسې سخت تکلیف سره مخامخ کړم چې هغه سړي ته مو وویل چې ستاسو بل ورور هم شته؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_6.mp3', '', 1761754199, 1761754199),
(46334, 'Genesis 43:7', 'Genesis', 43, 7, 'هغوی ځواب ورکړ: «هغه سړي په ډېر غور سره زمونږ او زمونږ د کورنۍ په اړه زمونږ څخه پوښتنې وکړې ویې ویل: ‹ایا ستاسو پلار تر‌اوسه پورې ژوندی دی؟ ستاسو بل ورور شته؟› مونږ یوازې د هغه پوښتنو ته ځواب ورکړی دی. مونږ څه پوهېدلو چې هغه به مونږ ته ووایي چې خپل ورور دلته راولئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_7.mp3', '', 1761754199, 1761754199),
(46335, 'Genesis 43:8', 'Genesis', 43, 8, 'یهودا خپل پلار یعقوب ته وویل: «هلک زما سره ولېږه. مونږ به سمدلاسه لاړ شو چې مونږ او تاسو او زمونږ ماشومان ژوندي پاتې شو او له لوږې څخه مړه نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_8.mp3', '', 1761754199, 1761754199),
(46336, 'Genesis 43:9', 'Genesis', 43, 9, 'زه په خپله د هغه د سلامتیا ضمانت کوم. ته کولای شې چې د هغه مسوولیت زما په غاړه واچوې. که چېرې هغه تاته رانه ولم او ستا په مخکې یې حاضر نه کړم، زه به تاته د تل دپاره ملامت یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_9.mp3', '', 1761754199, 1761754199),
(46337, 'Genesis 43:10', 'Genesis', 43, 10, 'که چېرې مونږ ځنډ نه وای کړی، نو تر‌اوسه پورې به مونږ دوه ځلې تللي او بېرته به راغلي وای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_10.mp3', '', 1761754199, 1761754199),
(46338, 'Genesis 43:11', 'Genesis', 43, 11, 'بیا د هغوی پلار یعقوب هغوی ته وویل: «که داسې وي، نو دا کار وکړئ. د خپل هېواد د ډېرو ښو پیداوارو څخه یو څه واخلئ او په خپلو بوجیو کې یې واچوئ او لږ څه ملهم، شات، مساله، د مر کنډ، پسته او بادام هغه سړي ته د سوغات په توګه یوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_11.mp3', '', 1761754199, 1761754199),
(46339, 'Genesis 43:12', 'Genesis', 43, 12, 'دوه چنده پیسې د ځان سره واخلئ، ځکه هغه پیسې چې بېرته ستاسو د بوجیو په خولو کې ایښودل شوې وې، باید بېرته ورکړئ. کېدای شي چې د هغوی څخه سهوه شوې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_12.mp3', '', 1761754199, 1761754199),
(46340, 'Genesis 43:13', 'Genesis', 43, 13, 'خپل ورور هم واخلئ او سمدلاسه بېرته هغه سړي ته ورشئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_13.mp3', '', 1761754199, 1761754199),
(46341, 'Genesis 43:14', 'Genesis', 43, 14, 'مطلق قادر خدای دې هغه سړی په تاسو باندې مهربانه کړي، ترڅو هغه بنیامین او ستاسو بل ورور بېرته تاسو ته درکړي. که چېرې زه بې‌اولاده کېږم، نو بې‌اولاده دې شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_14.mp3', '', 1761754199, 1761754199),
(46342, 'Genesis 43:15', 'Genesis', 43, 15, 'نو هغو ورونو سوغاتونه او دوه چنده پیسې واخیستلې او د بنیامین سره مصر ته روان شول او هغوی خپل ځانونه یوسف ته ورحاضر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_15.mp3', '', 1761754199, 1761754199),
(46343, 'Genesis 43:16', 'Genesis', 43, 16, 'کله چې یوسف د هغوی سره بنیامین ولیده، نو د خپل کور ناظر ته یې وویل: «دا خلک زما کور ته بوځه او یو حیوان حلال کړه او تیار یې کړه چې دوی به غرمه زما سره ډوډۍ خوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_16.mp3', '', 1761754199, 1761754199),
(46344, 'Genesis 43:17', 'Genesis', 43, 17, 'لکه څنګه چې یوسف امر کړی ؤ، هغه سړي هماغه شان وکړل او هغه خلک یې د یوسف کور ته راوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_17.mp3', '', 1761754199, 1761754199),
(46345, 'Genesis 43:18', 'Genesis', 43, 18, 'کله چې هغوی د یوسف کور ته راوستل شول، نو ووېرېدل. دوی فکر کاوه: «مونږ د هغو پیسو په سبب چې په لومړي ځل زمونږ په بوجیو کې بېرته ایښودل شوې وې، دلته راوستل شوي یو. هغه غواړي چې مونږ بندیان کړي، مونږ خپل غلامان کړي او زمونږ څخه خره واخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_18.mp3', '', 1761754199, 1761754199),
(46346, 'Genesis 43:19', 'Genesis', 43, 19, 'نو هغوی د یوسف ناظر ته ورغلل او د کور په دروازه کې یې د هغه سره خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_19.mp3', '', 1761754199, 1761754199),
(46347, 'Genesis 43:20', 'Genesis', 43, 20, 'هغوی وویل: «ای باداره! مونږ دلته یوځل مخکې د غلو دانو د اخیستلو دپاره راغلي وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_20.mp3', '', 1761754199, 1761754199),
(46348, 'Genesis 43:21', 'Genesis', 43, 21, 'خو کله چې په یو ځای کې د شپې تېرولو دپاره ودرېدلو، مونږ خپلې بوجۍ پرانیستلې او هر یو خپلې پیسې په هماغه خپله اندازه د خپلو بوجیو په خولو کې وموندلې. نو مونږ هغه بېرته د خپل ځان سره راوړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_21.mp3', '', 1761754199, 1761754199),
(46349, 'Genesis 43:22', 'Genesis', 43, 22, 'همدارنګه مونږ نورې پیسې هم د ځان سره راوړې دي چې نوره غله واخلو. مونږ نه پوهېږو چې چا زمونږ په بوجیو کې هغه پیسې ایښې وې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_22.mp3', '', 1761754199, 1761754199),
(46350, 'Genesis 43:23', 'Genesis', 43, 23, 'ناظر وویل: «اندېښنه مه کوئ او مه وېرېږئ. ستاسو او ستاسو د پلار خدای ستاسو په بوجیو کې تاسو ته خزانه ایښې ده. ستاسو پیسې ماته راورسېدلې.» نو شمعون یې هغوی ته راوست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_23.mp3', '', 1761754199, 1761754199),
(46351, 'Genesis 43:24', 'Genesis', 43, 24, 'ناظر د یوسف ورونه د هغه کور ته دننه بوتلل او هغوی ته یې اوبه ورکړې چې خپلې پښې ووینځي او د هغوی خرو ته یې واښه ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_24.mp3', '', 1761754199, 1761754199),
(46352, 'Genesis 43:25', 'Genesis', 43, 25, 'هغوی سوغاتونه تیار کړل چې یوسف به غرمې ته راشي، ځکه چې دوی ته ویل شوي وو چې ډوډۍ به هلته وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_25.mp3', '', 1761754199, 1761754199),
(46353, 'Genesis 43:26', 'Genesis', 43, 26, 'کله چې یوسف کور ته راغی، نو دوی هغه سوغاتونه چې کور ته یې راوړي وو، هغه ته وړاندې کړل او هغه ته یې د درناوي په خاطر خپل سرونه ټیټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_26.mp3', '', 1761754199, 1761754199),
(46354, 'Genesis 43:27', 'Genesis', 43, 27, 'هغه د دوی د روغتیا په هکله پوښتنه وکړه او بیا یې وویل: «ستاسو زوړ پلار چې تاسو د هغه په اړه ویلي وو، څنګه دی؟ ایا هغه تر‌اوسه پورې ژوندی دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_27.mp3', '', 1761754199, 1761754199),
(46355, 'Genesis 43:28', 'Genesis', 43, 28, 'هغوی وویل: «ستا غلام یعنې زمونږ پلار تر‌اوسه پورې ژوندی دی او ښه دی.» دوی د هغه په وړاندې د درناوي په خاطر خپل سرونه ټیټ کړل او پړمخې پرېوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_28.mp3', '', 1761754199, 1761754199),
(46356, 'Genesis 43:29', 'Genesis', 43, 29, 'کله چې یوسف خپل سکه ورور بنیامین ولیده، هغه پوښتنه وکړه: «ایا ستاسو کشر ورور چې تاسو ماته د هغه په اړه ویلي وو دا دی؟ ای زما زویه! خدای دې تاته برکت درکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_29.mp3', '', 1761754199, 1761754199),
(46357, 'Genesis 43:30', 'Genesis', 43, 30, 'یوسف سمدلاسه لاړ، ځکه چې د خپل ورور په لیدلو باندې ډېر احساساتي شو او د ژړا ځای یې لټاوه. هغه خپلې شخصي کوټې ته ننوت او هلته یې وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_30.mp3', '', 1761754199, 1761754199),
(46358, 'Genesis 43:31', 'Genesis', 43, 31, 'وروسته له هغې چې خپل مخ یې ووینځه، دباندې راووت. خپل ځان یې کنترول کړ او ویې ویل: «ډوډۍ راوړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_31.mp3', '', 1761754199, 1761754199),
(46359, 'Genesis 43:32', 'Genesis', 43, 32, 'یوسف ته یې په یو دسترخوان باندې ډوډۍ ورکړه او د هغه ورونو ته یې په بل دسترخوان باندې. مصریانو ته یې چې هلته یې ډوډۍ خوړله بېله کېښودله، ځکه چې هغوی به د عبرانیانو سره ډوډۍ نه خوړله. مصریانو د عبرانیانو سره ډوډۍ خوړل حرام ګڼل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_32.mp3', '', 1761754199, 1761754199),
(46360, 'Genesis 43:33', 'Genesis', 43, 33, 'د هغه ورونه د هغوی د عمر له مخې د مشر څخه تر کشره پورې د یوسف په مخکې کښېنول شول او هغوی په حیرانتیا سره یو بل ته کتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_33.mp3', '', 1761754199, 1761754199),
(46361, 'Genesis 43:34', 'Genesis', 43, 34, 'هغوی ته د یوسف د دسترخوان څخه ډوډۍ ورکړای شوه او د بنیامین برخه د نورو ټولو څخه پنځه چنده زیاته وه. نو هغوی د یوسف سره وخوړل او ویې څښل او خوشحالي یې وکړه ترڅو چې نشه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis43_verse_34.mp3', '', 1761754199, 1761754199),
(46362, 'Isaiah 23:1', 'Isaiah', 23, 1, 'دا پیغام د صور په هکله دی: ای د بحیرې کشتۍ چلوونکو، د صور دپاره له غمه چیغې ووهئ! ستاسو د صور بندر وران شوی او کورونه مو په کنډوالو بدل شوي دي. څه چې تاسو په قبرس کې اورېدلي دي، هغه رښتیا دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_1.mp3', '', 1761754199, 1761754199),
(46363, 'Isaiah 23:2', 'Isaiah', 23, 2, 'ای د بحیرې د غاړې اوسېدونکو! ای د صیدون سوداګرانو، ویر وکړئ! تاسو به له بحیرې څخه تېرېدلئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_2.mp3', '', 1761754199, 1761754199),
(46364, 'Isaiah 23:3', 'Isaiah', 23, 3, 'ترڅو د مصر څخه غلې دانې په بیه واخلئ او بیا یې په نورو خرڅې کړئ. په دې ډول تاسو د ټولو قومونو دپاره د سوداګرۍ مرکز وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_3.mp3', '', 1761754199, 1761754199),
(46365, 'Isaiah 23:4', 'Isaiah', 23, 4, 'ای د صیدون ښاره، ای د بحیرې د غاړې کلا، وشرمېږه! ځکه بحیره وایي: «ما هېڅکله د لنګون درد احساس نه کړ او زامن او لورګانې مې نه دي زېږولي. ما هېڅکله ماشومان نه دي لوی کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_4.mp3', '', 1761754199, 1761754199),
(46366, 'Isaiah 23:5', 'Isaiah', 23, 5, 'کله چې د صور بد خبر مصر ته ورسیږي، د هغه ځای خلک به ټکان وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_5.mp3', '', 1761754199, 1761754199),
(46367, 'Isaiah 23:6', 'Isaiah', 23, 6, 'ای د لېرې هېوادونو اوسېدونکو، له ډېره غمه چیغې ووهئ! کوښښ وکړئ چې هسپانیې ته وتښتئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_6.mp3', '', 1761754199, 1761754199),
(46368, 'Isaiah 23:7', 'Isaiah', 23, 7, 'ایا دا هماغه د صور خوشحاله ښار دی چې ډېر پخوا ودان شوی ؤ؟ ایا دا هماغه ښار دی چې خپل اوسېدونکي یې لېرې هېوادونو ته لېږل چې هلته استوګن شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_7.mp3', '', 1761754199, 1761754199),
(46369, 'Isaiah 23:8', 'Isaiah', 23, 8, 'چا دا نقشه درلودله چې په صور یعنې د پاچاهیو په جوړوونکي ښار باندې چې سوداګران یې شاهزاده ګان او د نړۍ عزتمن خلک وو، دا بلا او مصیبت راولي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_8.mp3', '', 1761754199, 1761754199),
(46370, 'Isaiah 23:9', 'Isaiah', 23, 9, 'مطلق قادر څښتن دا نقشه درلودله، ترڅو د هغوی شوکت او غرور له منځه لاړ شي او عزتمن خلک یې خوار او سپک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_9.mp3', '', 1761754199, 1761754199),
(46371, 'Isaiah 23:10', 'Isaiah', 23, 10, 'ای د هسپانیې خلکو، په خپل هېواد کې خواره واره شئ لکه څنګه چې د نیل سیند د غاړو څخه اوړي. اوس داسې څوک نشته چې ستاسو مخه ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_10.mp3', '', 1761754199, 1761754199),
(46372, 'Isaiah 23:11', 'Isaiah', 23, 11, 'څښتن خپل لاس په بحیرې باندې اوچت کړی دی او د نړۍ پاچاهۍ یې لړزولې دي. هغه حکم کړی چې د کنعان کلاګانې دې له منځه لاړې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_11.mp3', '', 1761754199, 1761754199),
(46373, 'Isaiah 23:12', 'Isaiah', 23, 12, 'هغه وویل: «ای د صیدون مظلومو خلکو، ستاسو خوشحالي پای ته ورسېدله. حتی که تاسو قبرس ته هم وتښتئ، هلته به هم هوسا او په امن کې ونه اوسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_12.mp3', '', 1761754199, 1761754199),
(46374, 'Isaiah 23:13', 'Isaiah', 23, 13, 'د بابل هېواد وګورئ چې د خلکو څخه خالي شوی دی. اشوریانو بابل د وحشي حیواناتو د منډې وهلو ځای جوړ کړی دی. هغوی د کلابندۍ د برجونو زینې جوړې، د بابلیانو کلاګانې یې ورانې او ښار یې په کنډوالې بدل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_13.mp3', '', 1761754199, 1761754199),
(46375, 'Isaiah 23:14', 'Isaiah', 23, 14, 'ای د بحیرې کشتۍ چلوونکو، له غمه وژاړئ! ځکه ستاسو د ښار کلا ورانه شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_14.mp3', '', 1761754199, 1761754199),
(46376, 'Isaiah 23:15', 'Isaiah', 23, 15, 'صور به د اویاو کالو دپاره چې د یو پاچا عمر دی هېر کړای شي. د دې کلونو د تېرېدلو نه وروسته به صور د یوې بدلمنې ښځې په شان وي چې په دې سندره کې یادیږي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_15.mp3', '', 1761754199, 1761754199),
(46377, 'Isaiah 23:16', 'Isaiah', 23, 16, 'ای هېره شوې بدلمنې خپل رباب راواخله او تاوه راتاوه شه د ښار نه ښه ساز غږوه او ډېرې سندرې ووایه چې خلک دې بیا یاده کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_16.mp3', '', 1761754199, 1761754199),
(46378, 'Isaiah 23:17', 'Isaiah', 23, 17, 'د اویا کالو نه وروسته به څښتن اجازه ورکړي چې صور بیا پرمختګ وکړي. لکه یوه بدلمنه ښځه چې خپل بدن په هر چا باندې خرڅ کړي، نو د پخوا په شان به د نړۍ د نورو هېوادونو سره تجارتي اړیکې ټینګې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_17.mp3', '', 1761754199, 1761754199),
(46379, 'Isaiah 23:18', 'Isaiah', 23, 18, 'خو د تجارت له لارې کومه ګټه چې هغوی لاسته راوړي هغه پیسې به ذخیره او پاسره نه شي، بلکې هغه به څښتن ته وقف شي. په دې پیسو باندې به د هغو خلکو دپاره چې د څښتن خدمت کوي، ډېر خواړه او ښایسته کالي واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah23_verse_18.mp3', '', 1761754199, 1761754199),
(46380, 'Jonah 4:1', 'Jonah', 4, 1, 'یونس په دې باندې ډېر خفه ؤ او په قهر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_1.mp3', '', 1761754199, 1761754199),
(46381, 'Jonah 4:2', 'Jonah', 4, 2, 'نو هغه داسې دعا وکړه او ویې ویل: «ای څښتنه، ایا دا هغه څه نه دي چې ما هغه وخت وویل کله چې زه په خپل وطن کې وم؟ له همدې امله ما بیړه وکړه چې ترشیش ته وتښتم، ځکه زه پوهېدم چې ته رحیم او مهربانه خدای یې. زر نه په قهرېږې او ستا تلپاتې مینه ډېره زیاته ده، تا خپله پرېکړه بدله کړې او خلکو ته به سزا ورنه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_2.mp3', '', 1761754199, 1761754199),
(46382, 'Jonah 4:3', 'Jonah', 4, 3, 'نو اوس ای څښتنه، زما ژوند واخله، ځکه چې زما دپاره د ژوند څخه مرګ ډېر ښه دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_3.mp3', '', 1761754199, 1761754199),
(46383, 'Jonah 4:4', 'Jonah', 4, 4, 'څښتن په ځواب کې وویل: «ته څه حق لرې چې په قهر شې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_4.mp3', '', 1761754199, 1761754199),
(46384, 'Jonah 4:5', 'Jonah', 4, 5, 'یونس د ښار ختیځ خواته لاړ او کښېناست. هغه د خپل ځان دپاره یو پناه ځای جوړ کړ او د هغې لاندې کښېناست، دا انتظار یې کاوه چې وویني په نینوا باندې به څه پېښ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_5.mp3', '', 1761754199, 1761754199),
(46385, 'Jonah 4:6', 'Jonah', 4, 6, 'بیا څښتن خدای یو بوټی راشین کړ چې په یونس باندې سیوری وکړي، ترڅو د هغه قهر سوړ کړي. یونس د بوټي دپاره ډېر خوشحاله شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_6.mp3', '', 1761754199, 1761754199),
(46386, 'Jonah 4:7', 'Jonah', 4, 7, 'خو په راتلونکې ورځ سهار وختي خدای یو چینجی راولېږه او هغه بوټی یې وخوړ او هغه وچ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_7.mp3', '', 1761754199, 1761754199),
(46387, 'Jonah 4:8', 'Jonah', 4, 8, 'کله چې لمر راوخوت، خدای د ختیځ له خوا تود باد راوالوزاوه او تر هغه وخته پورې لمر د یونس په سر باندې لګېده چې هغه کمزوری شو. هغه غوښتل چې مړ شي او ویې ویل: «زما دپاره د ژوند څخه مرګ ډېر ښه دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_8.mp3', '', 1761754199, 1761754199),
(46388, 'Jonah 4:9', 'Jonah', 4, 9, 'خو خدای هغه ته وویل:«ته څه حق لرې چې د بوټي په هکله په قهر شې؟» یونس په ځواب کې وویل: «زه حق لرم چې په قهر شم، دومره په قهر شم چې مړ شم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_9.mp3', '', 1761754199, 1761754199),
(46389, 'Jonah 4:10', 'Jonah', 4, 10, 'څښتن هغه ته وویل: «ته په دې بوټي باندې چې د هغه دپاره دې هېڅ زحمت نه دی ویستلی او نه دې لوی کړی دی، زړه سوځوې. دا بوټی په یوه شپه کې راشین شو او په بله شپه وچ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_10.mp3', '', 1761754199, 1761754199),
(46390, 'Jonah 4:11', 'Jonah', 4, 11, 'نو ایا زه د نینوا په لوی ښار باندې زړه ونه سوځوم؟ هلته د یو لک او شلو زرو څخه زیات خلک شته چې جاهلان دي او همدارنګه ډېر حیوانات په کې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah4_verse_11.mp3', '', 1761754199, 1761754199),
(46391, 'Isaiah 14:1', 'Isaiah', 14, 1, 'څښتن به یوځل بیا د یعقوب په اولادې باندې رحم وکړي او هغه به بیا اسراییل د خپل قوم په توګه غوره کړي. هغوی به پرېږدي چې بیا خپل وطن اباد کړي او هلته واوسیږي او پردي خلک به راشي او له هغوی سره به په یووالي کې ژوند وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_1.mp3', '', 1761754199, 1761754199),
(46392, 'Isaiah 14:2', 'Isaiah', 14, 2, 'نور قومونه به له اسراییلیانو سره مرسته وکړي چې هغوی بېرته د څښتن ځمکې ته راستانه شي او هلته به نوموړي قومونه لکه د غلامانو او وینځو په شان د اسراییلو خدمت کوي. کومو خلکو چې یو وخت یې اسراییلیان په اسارت نیولي وو اوس به اسراییلیان په هغو باندې حکومت کوي، چا چې یو وخت په هغوی باندې ظلم کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_2.mp3', '', 1761754199, 1761754199),
(46393, 'Isaiah 14:3', 'Isaiah', 14, 3, 'کله چې څښتن د اسراییلو خلک د هغوی له دردونو، کړاوونو او له هغو سختو کارونو په کولو چې هغوی مجبور وو، وژغوري،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_3.mp3', '', 1761754199, 1761754199),
(46394, 'Isaiah 14:4', 'Isaiah', 14, 4, 'هغه وخت به هغوی د بابل پاچا ته په ملنډو ووایي: «ګورئ، هغه ظالم پاچا له منځه تللی او ظلم یې پای ته رسېدلی دی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_4.mp3', '', 1761754199, 1761754199),
(46395, 'Isaiah 14:5', 'Isaiah', 14, 5, 'څښتن د بدکارانو لښته او د حکمرانانو امسا ماته کړې ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_5.mp3', '', 1761754199, 1761754199),
(46396, 'Isaiah 14:6', 'Isaiah', 14, 6, 'چا چې به په قهر او غضب سره تل په خلکو باندې ظلم کاوه او د هغو قومونو له ځورولو به یې لاس نه اخیست چې تسلیم شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_6.mp3', '', 1761754199, 1761754199),
(46397, 'Isaiah 14:7', 'Isaiah', 14, 7, 'اوس ټوله نړۍ له ارامۍ او سولې خوند اخلي او هر یو د خوشحالۍ سندرې وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_7.mp3', '', 1761754199, 1761754199),
(46398, 'Isaiah 14:8', 'Isaiah', 14, 8, 'حتی د لبنان د سروې او سبر ونې د پاچا په سقوط باندې خوشحالي کوي او وایي: ‹اوس چې ته رانسکور شوی یې، داسې څوک نشته چې مونږ ووهي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_8.mp3', '', 1761754199, 1761754199),
(46399, 'Isaiah 14:9', 'Isaiah', 14, 9, 'د مړو دنیا په ډېر احساساتي توګه ستا د راتللو انتظار کوي. د ځمکې د ټولو مشرانو ارواحګانې راپارول کیږي چې ستا هرکلي ته ودریږي. حتی د ټولو پاچاهانو ارواحګانې له خپلو تختونو راپورته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_9.mp3', '', 1761754199, 1761754199),
(46400, 'Isaiah 14:10', 'Isaiah', 14, 10, 'هغه ټول به تاته ووایي: ‹ته اوس زمونږ په شان کمزوری شوی یې! ته اوس زمونږ په شان یې!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_10.mp3', '', 1761754199, 1761754199),
(46401, 'Isaiah 14:11', 'Isaiah', 14, 11, 'د چنګ په وهلو به ستا درناوی کېده، خو اوس ستا شان او شوکت ستا سره په ګور کې ښخ شوی دی. ته د خوځنده چینجیو په بستره کې پروت او د چینجیو په کمپله کې پټ یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_11.mp3', '', 1761754199, 1761754199),
(46402, 'Isaiah 14:12', 'Isaiah', 14, 12, 'ای د بابل پاچا، ای د سهار روښانه ستوریه، ته له اسمان نه څنګه راولوېدلې! تا خو قومونه فتح کول، خو اوس ته په ځمکه راغورځول شوی یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_12.mp3', '', 1761754199, 1761754199),
(46403, 'Isaiah 14:13', 'Isaiah', 14, 13, 'تا په خپل زړه کې ویل: «اسمان ته به وخېژم او خپل تخت به د خدای د ستورو دپاسه کېږدم. په شمال کې به په هغه غره باندې چې خدایان راټولیږي، کښېنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_13.mp3', '', 1761754199, 1761754199),
(46404, 'Isaiah 14:14', 'Isaiah', 14, 14, 'د ورېځو دپاسه به وخېژم او د خدای تعالی په شان به شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_14.mp3', '', 1761754199, 1761754199),
(46405, 'Isaiah 14:15', 'Isaiah', 14, 15, 'خو د هغې په ځای، ته د مړو د دنیا ډېرې ژورې کندې ته راوړل شوی یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_15.mp3', '', 1761754199, 1761754199),
(46406, 'Isaiah 14:16', 'Isaiah', 14, 16, 'کله چې مړي تا وویني، هغوی به تاته په ځیر ځیر وګوري، په فکر کې به ډوب شي او پوښتنه به وکړي: «ایا دا هغه سړی نه دی چې ځمکه یې خوځوله او د نړۍ پاچاهان د ده له وېرې لړزېدل؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_16.mp3', '', 1761754199, 1761754199),
(46407, 'Isaiah 14:17', 'Isaiah', 14, 17, 'ایا دا هم هغه سړی نه دی چې ښارونه یې وران کړل او نړۍ یې په دښته باندې بدله کړه؟ ایا دا هماغه سړی نه دی چې هېڅکله یې خپل اسیران نه ازادول او نه یې پرېښودل چې خپلو کورونو ته لاړ شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_17.mp3', '', 1761754199, 1761754199),
(46408, 'Isaiah 14:18', 'Isaiah', 14, 18, 'د نړۍ ټول پاچاهان د شان او شوکت سره په قبرونو کې پراته دي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_18.mp3', '', 1761754199, 1761754199),
(46409, 'Isaiah 14:19', 'Isaiah', 14, 19, 'خو ته قبر هم نه لرې او ستا مړی لکه د خوسا شوې څانګې په شان لېرې غورځول شوی دی. ستا مړی د هغو عسکرو د مړو لاندې پټ دی چې په جګړې کې وژل شوي او د هغوی سره یوځای د تیږو یوې کندې ته غورځول شوی او تر پښو لاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_19.mp3', '', 1761754199, 1761754199),
(46410, 'Isaiah 14:20', 'Isaiah', 14, 20, 'په دې خاطر چې تا خپل وطن وران کړی او خپل خلک دې وژلي دي، نو ځکه ته به د نورو پاچاهانو په شان ښخ نه شې. ستا بدکار نه به نسل پاتې نه شي او خلک به تا هېڅ وخت یاد نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_20.mp3', '', 1761754199, 1761754199);